/** A code the routes can answer. */
export type AuthErrorCode = keyof typeof AUTH_ERROR_CODES;

/** The body of every error answer: `{ error: { code, message } }` with the status of the code. */
export interface AuthErrorBody {
  error: { code: AuthErrorCode | (string & {}); message: string };
}

/** Whether a code is one this list knows, narrowing it to AuthErrorCode. */
export function isAuthErrorCode(code: string): code is AuthErrorCode {
  return Object.prototype.hasOwnProperty.call(AUTH_ERROR_CODES, code);
}
